INSERT INTO public.projects (title, slug, client, category, description, results, services, tags, cover_url, thumbnail_url, featured, published, sort_order, project_date) VALUES
('Nova Coffee — Brand Identity', 'nova-coffee-brand-identity', 'Nova Coffee Co.', 'Branding', 'A complete identity redesign for a specialty coffee chain — logo system, packaging, signage and a launch campaign that filled three new locations on opening week.', '+340% Instagram engagement · 12k new followers in 60 days · 3 stores sold out at launch', ARRAY['Branding','Packaging','Launch Campaign'], ARRAY['branding','packaging','retail'], 'https://images.unsplash.com/photo-1511920170033-f8396924c348?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1511920170033-f8396924c348?w=900&q=80&auto=format&fit=crop', true, true, 1, '2025-08-01'),
('Aurora Residences — Real Estate Campaign', 'aurora-residences-campaign', 'Aurora Group', 'Paid Ads', 'Cinematic launch campaign for a luxury residential project — from creative direction and 4K video shoots to a multi-channel paid media plan.', '128 qualified leads in 21 days · 6.4M impressions · CPL reduced by 58%', ARRAY['Video Production','Paid Ads','Web Design'], ARRAY['real-estate','luxury','video'], 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?w=900&q=80&auto=format&fit=crop', true, true, 2, '2025-09-15'),
('Maison Lina — Fashion Social', 'maison-lina-fashion-social', 'Maison Lina', 'Social Media', 'Editorial social strategy for an independent fashion house — monthly content shoots, reels production, and community building across IG and TikTok.', '+540% reach growth · 1.8M monthly views · sold-out capsule drop', ARRAY['Content Creation','Social Media','Strategy'], ARRAY['fashion','social','editorial'], 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?w=900&q=80&auto=format&fit=crop', true, true, 3, '2025-10-10'),
('Olive & Stone — Restaurant Launch', 'olive-and-stone-launch', 'Olive & Stone', 'Branding', 'Full brand build for a Mediterranean restaurant — naming, identity, menu system, photography and a launch reel that booked the first month solid.', 'Fully booked first 30 nights · 22k followers in 90 days · featured by 4 local press outlets', ARRAY['Branding','Photography','Web Design','Launch Campaign'], ARRAY['restaurant','hospitality','launch'], 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=900&q=80&auto=format&fit=crop', true, true, 4, '2025-11-05'),
('Helio Skin — Luxury Product Launch', 'helio-skin-launch', 'Helio Skin', 'Content Creation', 'Premium product launch for a skincare brand — concept, art direction, hero film, and 90-day content engine.', 'Sold out in 11 days · 4.2M video views · 38% repeat purchase rate', ARRAY['Content Creation','Video Production','Paid Ads'], ARRAY['beauty','luxury','launch'], 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?w=900&q=80&auto=format&fit=crop', true, true, 5, '2025-12-01'),
('Vertex Studio — Web Redesign', 'vertex-studio-web', 'Vertex Studio', 'Web Design', 'A site rebuild for a creative production studio — modern, fast, and engineered around their case studies.', 'Bounce rate down 41% · qualified inquiries up 3.2x · Lighthouse 98', ARRAY['Web Design','Branding'], ARRAY['web','studio','agency'], 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?w=1600&q=80&auto=format&fit=crop', 'https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?w=900&q=80&auto=format&fit=crop', false, true, 6, '2026-01-12')
